&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;We are not here to sell AI theatre. We are here to turn AI into&amp;nbsp;working systems, measurable&amp;nbsp;outcomes&amp;nbsp;and repeatable transformation programs.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:140,&amp;quot;335559740&amp;quot;:252}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About the role&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span class=&quot;TextRun SCXW21516603 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW21516603 BCX8&quot; data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;We&#39;re&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW21516603 BCX8&quot; data-ccp-parastyle=&quot;Normal (Web)&quot;&gt; looking for a &lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW21516603 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW21516603 BCX8&quot; data-ccp-parastyle=&quot;Normal (Web)&quot;&gt;Senior Automation Engineer&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;TextRun SCXW21516603 BCX8&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW21516603 BCX8&quot; data-ccp-parastyle=&quot;Normal (Web)&quot;&gt; to own the technical delivery of UiPath automation workstreams end-to-end — from design and development through testing and deployment — working with international clients across a distributed, global delivery environment.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW21516603 BCX8&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Responsibilities and tasks for this role&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
